import csv
import os


class CSVProcessor:

    def __init__(self):
        pass

    def _validate_row_index(self, data, index):
        """Check if the column index is valid for all rows in the data."""
        if not data:
            return False
        row_length = len(data[0])
        return 0 <= index < row_length

    def read_csv(self, file_name):
        data = []
        with open(file_name, 'r') as file:
            reader = csv.reader(file)
            title = next(reader)
            for row in reader:
                data.append(row)
        return title, data

    def write_csv(self, data, file_name):
        try:
            with open(file_name, 'w', newline='') as file:
                writer = csv.writer(file)
                writer.writerows(data)
            return 1
        except:
            return 0

    @staticmethod
    def _extract_column(data, column_index):
        """Extract a specific column from the data."""
        column_data = [row[column_index] for row in data]
        return column_data

    @staticmethod
    def _uppercase_column_data(column_data):
        """Convert all entries in the column data to uppercase."""
        return [row.upper() for row in column_data]

    @staticmethod
    def _generate_output_file_name(input_file_name):
        """Generate the output file name by appending '_process' before the extension."""
        base_name, extension = os.path.splitext(input_file_name)
        return f"{base_name}_process{extension}"

    def process_csv_data(self, N, save_file_name):
        title, data = self.read_csv(save_file_name)

        if not data:
            return 0

        if not self._validate_row_index(data, N):
            return 0

        column_data = self._extract_column(data, N)
        column_data = self._uppercase_column_data(column_data)

        new_data = [title, column_data]
        output_file_name = self._generate_output_file_name(save_file_name)
        return self.write_csv(new_data, output_file_name)
